function createPackedPbr(name,{roughness=.75,metallic=.05,scale=4}={}){const size=256,normal=new BABYLON.DynamicTexture(`${name}-normal`,{width:size,height:size},scene,false),nctx=normal.getContext();nctx.fillStyle="#8080ff";nctx.fillRect(0,0,size,size);for(let i=0;i<900;i++){const shade=116+Math.floor(Math.random()*25);nctx.fillStyle=`rgb(${shade},${shade},255)`;const radius=.4+Math.random()*1.8;nctx.fillRect(Math.random()*size,Math.random()*size,radius,radius)}normal.update(false);normal.gammaSpace=false;normal.wrapU=normal.wrapV=BABYLON.Texture.WRAP_ADDRESSMODE;normal.uScale=normal.vScale=scale;normal.anisotropicFilteringLevel=8;const packed=new BABYLON.DynamicTexture(`${name}-orm`,{width:size,height:size},scene,false),pctx=packed.getContext(),image=pctx.createImageData(size,size),data=image.data,r=Math.round(roughness*255),m=Math.round(metallic*255);for(let i=0;i<data.length;i+=4){const grain=Math.floor((Math.random()-.5)*24);data[i]=Math.max(150,232+grain);data[i+1]=Math.max(0,Math.min(255,r+grain));data[i+2]=m;data[i+3]=255}pctx.putImageData(image,0,0);packed.update(false);packed.gammaSpace=false;packed.wrapU=packed.wrapV=BABYLON.Texture.WRAP_ADDRESSMODE;packed.uScale=packed.vScale=scale;packed.anisotropicFilteringLevel=8;return{normal,packed}}
