const QUALITY_PRESETS=GRAPHICS_CONFIG.presets;
function applyQuality(name){
  const preset=QUALITY_PRESETS[name]||QUALITY_PRESETS.medium;
  state.quality=QUALITY_PRESETS[name]?name:"medium";
  engine.setHardwareScalingLevel(1/Math.min(devicePixelRatio||1,preset.pixelRatio));
  renderPipeline.samples=preset.samples;renderPipeline.fxaaEnabled=preset.fxaa;renderPipeline.bloomEnabled=preset.bloom;renderPipeline.bloomWeight=preset.bloomWeight;renderPipeline.bloomKernel=name==="high"?40:28;renderPipeline.sharpenEnabled=preset.sharpen;
  const shadowMap=shadows.getShadowMap();if(shadowMap&&shadowMap.getSize().width!==preset.shadowMap)shadowMap.resize(preset.shadowMap);shadows.filteringQuality=name==="high"?BABYLON.ShadowGenerator.QUALITY_MEDIUM:BABYLON.ShadowGenerator.QUALITY_LOW;shadows.setDarkness(name==="low"?.18:.14);moon.shadowEnabled=preset.shadows;scene.fogDensity=preset.fog;
  if(atmosphere)atmosphere.emitRate=Math.round(22*preset.particles);
  [groundSurface,asphaltSurface,metalSurface,weaponMetal,skinSurface,fabricSurface].forEach(texture=>texture.anisotropicFilteringLevel=preset.anisotropy);
  if(qualitySelect)qualitySelect.value=state.quality;
  try{localStorage.setItem("project-gun-quality",state.quality)}catch{}
  engine.resize();
}
let savedQuality="medium";try{savedQuality=localStorage.getItem("project-gun-quality")||"medium"}catch{}
applyQuality(savedQuality);qualitySelect?.addEventListener("change",event=>applyQuality(event.target.value));

function worldBox(name,p,s,mat=mats.wall,solid=true){const mesh=BABYLON.MeshBuilder.CreateBox(name,{width:s.x,height:s.y,depth:s.z},scene);mesh.position.copyFrom(p);mesh.material=mat;mesh.checkCollisions=solid;mesh.receiveShadows=true;mesh.metadata={solid};return mesh;}
