function noiseBurst(duration=.1,volume=.1,low=7000,high=45,position=null,delay=0){const ac=initAudio();if(!ac)return;const source=ac.createBufferSource(),lowpass=ac.createBiquadFilter(),highpass=ac.createBiquadFilter(),gain=ac.createGain(),start=ac.currentTime+delay;source.buffer=state.noiseBuffer;lowpass.type="lowpass";lowpass.frequency.value=low;highpass.type="highpass";highpass.frequency.value=high;gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(volume,start+.003);gain.gain.exponentialRampToValueAtTime(.0001,start+duration);source.connect(lowpass);lowpass.connect(highpass);highpass.connect(gain);gain.connect(audioBus(position));source.start(start,Math.random());source.stop(start+duration+.03)}
