function playGunSound(kind){const pitchVar=1+(Math.random()-.5)*.12;if(kind==="shotgun"){noiseBurst(.16,.17,1750,65);synth(94*pitchVar,.13,"square",.045,null,0,28);synth(54*pitchVar,.18,"sawtooth",.07,null,.018,15)}else if(kind==="smg"){noiseBurst(.055,.055,3900*pitchVar,260);synth(155*pitchVar,.052,"square",.014,null,0,48)}else if(kind==="pistol"){noiseBurst(.075,.075,4400*pitchVar,270);synth(185*pitchVar,.064,"square",.019,null,0,58)}else if(kind==="switch"){synth(400*pitchVar,.04,"square",.018);noiseBurst(.025,.035,6000,500)}else if(kind==="dry"){synth(760*pitchVar,.025,"square",.012);synth(210,.035,"triangle",.007,null,.018,150)}else if(kind==="landing"){noiseBurst(.09,.1,1150,90);synth(58,.11,"sawtooth",.028)}else if(kind==="heartbeat"){synth(50,.1,"sine",.045);setTimeout(()=>synth(45,.12,"sine",.045),200)}else{noiseBurst(.095,.105,2400*pitchVar,170);synth(118*pitchVar,.085,"square",.026,null,0,38);synth(76*pitchVar,.1,"sawtooth",.032,null,.018,18)}}
