function beginWave(index){const wave=WAVES[index];state.waveIndex=index;state.waveKills=0;state.waveTarget=wave.count;state.spawnRemaining=wave.count;state.spawnTimer=.45;state.waveActive=true;state.intermission=0;labels.objectiveTitle.textContent=`DALGA ${index+1} / ${WAVES.length} · ${wave.label}`;labels.objectiveText.innerHTML=`<b id="kill-count">0</b> / <span id="kill-target">${wave.count}</span> zombi etkisiz`;labels.killCount=$("kill-count");labels.killTarget=$("kill-target");showWaveBanner(`DALGA ${index+1}`,wave.label);addFeed(`DALGA ${index+1} BAŞLADI`,"#ff5b35");synth(62,.55,"sawtooth",.045,null,0,42);synth(94,.38,"triangle",.03,null,.12,55);updateHud()}
function finishWave(){state.waveActive=false;if(state.waveIndex>=WAVES.length-1){activateExtraction();return}state.intermission=7;labels.objectiveTitle.textContent=`DALGA ${state.waveIndex+1} TAMAMLANDI`;showWaveBanner("BÖLGE TEMİZ",`DALGA ${state.waveIndex+2} HAZIRLANIYOR`,"#66e3ee");state.health=Math.min(100,state.health+18);state.armor=Math.min(100,state.armor+15);const reserveCaps={rifle:210,smg:240,shotgun:56,pistol:105};LOADOUT.forEach(w=>{if(w.kind!=="knife")w.reserve=Math.min(reserveCaps[w.kind],w.reserve+Math.ceil(w.mag*.7))});updateHud()}

