function addEffect(mesh,life,velocity=BABYLON.Vector3.Zero(),fade=true,poolKey=null){state.effects.push({mesh,life,maxLife:life,velocity,fade,poolKey});const limit=state.quality==="low"?36:72;if(state.effects.length>limit){const old=state.effects.shift();recycleMesh(old.poolKey,old.mesh)}return mesh}
