function spawnImpact(point,mesh,normal,audible=true){const surface=surfaceFromMesh(mesh),amount=Math.max(1,Math.round((state.quality==="high"?5:3)*QUALITY_PRESETS[state.quality].particles)),poolKey=`impact-${surface}`;for(let i=0;i<amount;i++){const chip=acquireMesh(poolKey,()=>BABYLON.MeshBuilder.CreateBox(`${surface}-impact`,{size:1},scene)),size=.025+Math.random()*.035;chip.position.copyFrom(point);chip.scaling.setAll(size);chip.material=surface==="metal"?mats.brass:surface==="wood"?mats.wood:dustMaterial;chip.isPickable=false;const n=normal?.clone()||new BABYLON.Vector3(0,1,0),velocity=n.scale(.7+Math.random()*1.4).add(new BABYLON.Vector3((Math.random()-.5)*1.4,Math.random()*.8,(Math.random()-.5)*1.4));addEffect(chip,.28+Math.random()*.3,velocity,true,poolKey)}if(audible)playImpact(point,false,surface)}
